    const pkg = require(path.resolve(
        __dirname,
        './packages',
        dirName,
        'package.json'
    ));
    mapper[`^${pkg.name}(.*)$`] = path.join(
        __dirname,
        `./packages/${dirName}/src$1`
    );
    return mapper;
}, {});

